<?php
namespace App\Database\Seeds;use CodeIgniter\Database\Seeder;
class PhaseFourSeeder extends Seeder{public function run():void{$districts=json_decode(file_get_contents(__DIR__.'/data/bd-districts.json'),true,512,JSON_THROW_ON_ERROR);$upazilas=json_decode(file_get_contents(__DIR__.'/data/bd-upazilas.json'),true,512,JSON_THROW_ON_ERROR);$map=[];foreach($districts as $i=>$d){$existing=$this->db->table('bd_districts')->where('name_en',$d['name']['en'])->get()->getRowArray();if(!$existing){$this->db->table('bd_districts')->insert(['division_name'=>$d['parent']['name']['en'],'name_en'=>$d['name']['en'],'name_bn'=>$d['name']['local'],'sort_order'=>$i,'status'=>'active']);$id=$this->db->insertID();}else$id=$existing['id'];$map[$d['id']]=$id;}foreach($upazilas as $i=>$u){$districtId=$map[$u['parent']['id']]??null;if(!$districtId)continue;if(!$this->db->table('bd_upazilas')->where(['district_id'=>$districtId,'name_en'=>$u['name']['en']])->get()->getRowArray())$this->db->table('bd_upazilas')->insert(['district_id'=>$districtId,'name_en'=>$u['name']['en'],'name_bn'=>$u['name']['local'],'sort_order'=>$i,'status'=>'active']);}$defs=['orders.view'=>['View Orders','orders'],'orders.manage'=>['Manage Orders','orders'],'payments.verify'=>['Verify Payments','payments'],'delivery.manage'=>['Manage Delivery','delivery']];$now=date('Y-m-d H:i:s');foreach($defs as $slug=>[$name,$module])if(!$this->db->table('admin_permissions')->where('slug',$slug)->get()->getRowArray())$this->db->table('admin_permissions')->insert(compact('name','slug','module')+['description'=>$name,'created_at'=>$now,'updated_at'=>$now]);foreach(['admin','manager'] as $roleSlug){$role=$this->db->table('admin_roles')->where('slug',$roleSlug)->get()->getRowArray();if(!$role)continue;foreach(array_keys($defs) as $slug){$p=$this->db->table('admin_permissions')->where('slug',$slug)->get()->getRowArray();if(!$this->db->table('admin_role_permissions')->where(['role_id'=>$role['id'],'permission_id'=>$p['id']])->get()->getRowArray())$this->db->table('admin_role_permissions')->insert(['role_id'=>$role['id'],'permission_id'=>$p['id'],'created_at'=>$now]);}}}}
